// Stable lesson IDs preserve existing browser progress.
const learningGroups=[
 {title:'先把基础说清楚',desc:'分清单位、参与者与交易发生的时间。',ids:[0,1,2]},
 {title:'价格为什么会变化',desc:'先看出清，再动手计算，最后理解合同如何管理风险。',ids:[4,6,3]},
 {title:'从电量算到电费',desc:'理解结算、系统服务与网络约束。',ids:[7,5,8]},
 {title:'把知识用到真实项目',desc:'阅读地区规则、复盘风险，再进入光储盈利规划。',ids:[9,10,11,12]}
];
lessons.push({id:12,stage:3,title:'光储方案：节省电费就是盈利吗？',desc:'把运行毛收益、投资成本和收益资格分开看。',minutes:12,sections:[['先画出能量流','光伏可以供本地负荷，也可能形成余电。储能把电量从一个时段移到另一个时段，但充放电有损耗。先确认电从哪里来、到哪里去，再算钱。'],['一个小算例','从电网充入 100 kWh，往返效率 88%，可放出 88 kWh。充电单价 0.30 元/kWh，放电替代的购电单价 0.80 元/kWh：运行毛收益 = 88 × 0.80 − 100 × 0.30 = 40.40 元。'],['从毛收益到项目现金流','40.40 元还没有扣除设备投资、运维、更换、税费和融资。辅助服务、容量或需求响应收益需要资格、合同与履约证据，不能直接叠加。先用完整成本与当地适用规则核对，再进入规划工具。']],quiz:{q:'上述 40.40 元应如何理解？',options:['整个项目的最终利润','未扣投资和运维的运行毛收益','按各省统一补贴形成的收益'],answer:1,explain:'这是充放电能量价差扣除购电成本后的运行毛收益，项目盈利还要看全周期成本。'}});
learningGroups.forEach((g,i)=>{Object.assign(stages[i],{title:g.title,desc:g.desc});g.ids.forEach(id=>lessons.find(l=>l.id===id).stage=i)});
const learningOrder=learningGroups.flatMap(g=>g.ids);
const lessonGuides={
 0:{goal:'把功率、时间、电量和费用四个量对应起来。',pre:[],terms:['MW / kW','MWh / kWh'],example:['从电器开始','2 kW 电器运行 3 小时，用电 6 kWh。把规模放大：2 MW 运行 3 小时，用电 6 MWh。单位要成对使用。'],task:['50 MW 连续运行 30 分钟，产生多少 MWh？',25,'MWh','先把 30 分钟换成 0.5 小时，再算 50 × 0.5。']},
 1:{goal:'说清谁发电、谁买电、谁组织交易。',pre:[0],terms:['售电公司','批发与零售'],example:['同一度电，两层合同','工厂与售电公司签零售合同，售电公司可能再向发电企业购电。工厂实际支付的价格要看零售合同，不能直接拿某个批发现货价替代。']},
 2:{goal:'按时间排出中长期、日前和实时三个环节。',pre:[1],terms:['中长期','日前 / 实时'],example:['明天要用 100 MWh','提前估计明天需要 100 MWh，实际用了 110 MWh。多出的 10 MWh 是理解实时调整的起点；结算金额还取决于适用合同和市场规则。']},
 4:{goal:'用供给排序判断谁形成边际价格。',pre:[2],terms:['出清','边际机组'],example:['用购物理解供给排序','先买便宜供给，不够时再用下一档。A 最多 80 MW，B 再提供 100 MW；需求超过 180 MW 后，需要 C。在统一边际价格模型里，价格就换到 C 的报价。']},
 6:{goal:'独立算出每台机组的中标出力。',pre:[4],terms:['出清','MW / kW'],example:['从总量检查答案','需求 150 MW 时，A 80 + B 70 + C 0 = 150 MW。检查出力总和等于需求，并且每台不超过容量。价格看最后需要调用的机组。'],task:['需求 175 MW 时，A 满发 80 MW，B 应出力多少 MW？',95,'MW','175 − 80 = 95 MW，没有超过 B 的 100 MW 容量。']},
 3:{goal:'区分合同覆盖电量与暴露于现货价格的电量。',pre:[6],terms:['中长期','敞口'],example:['先拆电量，再写公式','实际 100 MWh、合同 80 MWh，可以理解为合同覆盖 80 MWh，剩余 20 MWh 保留现货敞口。在本简化差价模型里，80 × 350 + 20 × 500 = 38,000 元。'],task:['实发 110 MWh、合同 80 MWh；合同价 350、现货价 500 元/MWh，简化总收入是多少元？',43000,'元','80 × 350 + (110 − 80) × 500 = 43,000 元。']},
 7:{goal:'把日前部分和实时偏差分别计算，再相加。',pre:[3],terms:['偏差电量','日前 / 实时'],example:['先看偏差的正负','日前 100 MWh，实际 95 MWh，偏差为 −5 MWh。日前价 300、实时价 450 元/MWh，简化成本为 30,000 − 2,250 = 27,750 元。'],task:['日前 100 MWh，实际 92 MWh，日前价 300、实时价 450 元/MWh，成本是多少元？',26400,'元','100 × 300 + (92 − 100) × 450 = 26,400 元。负偏差是差额结算方向，不是负的用电量。']},
 5:{goal:'把电能量、系统服务和环境权益分开。',pre:[7],terms:['辅助服务','绿证'],example:['先确认你卖的是什么','卖电量、提供调频服务、转让环境权益，是不同交易对象。即使它们来自同一个项目，也要按适用规则核对计量、资格和是否允许重复获得收益。']},
 8:{goal:'解释便宜电源为何不能总是供给所有地点。',pre:[4,7],terms:['节点电价','阻塞'],example:['一条容量有限的线路','便宜电源到工厂的线路只能送 50 MW，工厂却需要 80 MW。其余需求可能需要本地较贵电源满足。这说明位置和约束会影响价格；此处没有进行完整潮流求解。']},
 9:{goal:'找到版本、适用主体和结算章节，再提取参数。',pre:[7],terms:['文件效力','口径'],example:['带一个问题去阅读','问题：这条规则适用于我的用户还是发电项目？先看总则与主体，再看计量结算；记录文件名、文号、页码与例外。解读用于辅助理解，不能替代正文。']},
 10:{goal:'在相同单位、主体和时段下比较省份。',pre:[9],terms:['口径','批发与零售'],example:['先把单位统一','甲材料写 500 元/MWh，乙材料写 0.50 元/kWh，换算后数值相同。但即使数值相同，也还要确认是批发价还是用户到户价、适用哪个月份和主体。']},
 11:{goal:'用电量和价格的分解解释结果变化。',pre:[3,7],terms:['敞口','偏差电量'],example:['总电费涨了，先别急着下结论','可能是用电量变多、价格变高，或合同覆盖与实际曲线错位。先固定电量比较价格，再固定价格比较电量，最后检查其他费用和结算条款。']},
 12:{goal:'分清储能运行毛收益与全周期项目盈利。',pre:[0,7,9],terms:['往返效率','现金流'],example:['换一个价格再算','仍充入 100 kWh、放出 88 kWh，若放电替代价格只有 0.40 元/kWh，运行毛收益为 88 × 0.40 − 100 × 0.30 = 5.20 元。相同设备，价差变化会显著改变收益。'],task:['充入 100 kWh、效率 88%，充电价 0.30、替代购电价 0.50 元/kWh，运行毛收益是多少元？',14,'元','100 × 0.88 × 0.50 − 100 × 0.30 = 14 元；还没有扣除投资与运维。']}
};
const glossary={
 'MW / kW':'功率：某一时刻的出力或用电速度。1 MW = 1,000 kW。',
 'MWh / kWh':'电量：一段时间内累积的用电或发电。1 MWh = 1,000 kWh；功率 × 小时 = 电量。',
 '售电公司':'为用户提供购电和零售服务的经营主体，合同规定价格与风险分配。',
 '批发与零售':'批发是市场主体之间的交易；零售是售电公司与用户的合同关系，价格口径可能不同。',
 '中长期':'为未来期间安排的电量和价格交易，具体交割与结算按适用规则。',
 '日前 / 实时':'日前围绕运行日前的安排；实时处理临近运行的变化。教学模型先分清计划与实际。',
 '出清':'按市场模型与约束，确定成交电量、出力和价格的过程。',
 '边际机组':'在单节点教学模型里，为满足需求最后需要调用的机组。',
 '敞口':'仍会受到价格或电量变化影响的部分。合同不一定覆盖全部风险。',
 '偏差电量':'实际电量与参考计划或合同电量之差；先确认参考对象、时段和单位。',
 '辅助服务':'调频、备用等维护系统运行的服务，与电能量交易分别核算。',
 '绿证':'可再生能源电力环境属性的凭证，收益与划转需核对适用政策。',
 '节点电价':'在特定电网位置增加单位负荷的边际成本，可能受到网络约束影响。',
 '阻塞':'输电容量或安全约束限制了电力输送。',
 '文件效力':'区分正式文件、征求意见稿、解读、历史版本，并确认生效和修订关系。',
 '口径':'一个量是按什么主体、范围、时间和方法计算的。比较前要统一口径。',
 '往返效率':'一个充放电过程放出电量与充入电量的比例，差额主要对应损耗。',
 '现金流':'按期间记录收入与支出；项目评估还需要完整投资、运维及更换等成本。'
};
// Plausible alternatives replace unrelated distractors; answer positions stay stable.
const betterOptions={0:['20 MWh','80 MWh','20 MW'],1:['只核对批发现货价格','核对零售合同与适用结算规则','只核对用户总用电量'],2:['锁定未来一年的合同价格','处理临近运行的供需偏差','为每个用户设定固定零售价格'],3:['现货价格','全部按合同价格锁定','不计价格的固定收益'],4:['最高报价的未中标机组','最后需要调用的边际机组','最低报价的中标机组'],5:['维护系统频率稳定','转移绿色环境权益','锁定所有用户的购电单价'],6:['40 MW','120 MW','100 MW'],7:['33,000 元','49,500 元','34,500 元'],8:['电网输送存在约束','所有位置必须采用同一价格','低价电源可以无约束输送'],9:['先照抄一个价格参数','先核对版本、效力和适用范围','先用外省同名规则替代'],10:['只核对价格数值是否相同','核对单位、主体、时段与版本','只核对发布机构是否相同'],11:['只比较总电费的增减','分解合同、偏差与价格影响','把变化全部归因于平均价格']};
lessons.forEach(l=>{if(betterOptions[l.id])l.quiz.options=betterOptions[l.id]});
function learningNext(){return learningOrder.find(id=>!completed.includes(id))??learningOrder[0]}
function labTeachingHint(id){const hints={energy:['0','如果运行时间翻倍，电量和电能量费用会怎样变化？','只把运行时长从 0.25 改为 0.5 小时，其他条件保持不变。'],clearing:['4','需求从 150 增至 190 MW，是否需要调用 C？价格由谁决定？','先比较 150、180、181 MW，观察跨过容量边界时的变化。'],contract:['3','实际电量等于合同电量时，现货价格变化还会影响总收入吗？','先把实际和合同都设为 80 MWh，再只改变现货价格。'],settlement:['7','实际电量低于日前电量时，偏差电量的符号是什么？','先比较实际 110 和 90 MWh，其余价格与日前电量保持不变。']};const h=hints[id];return `<div class="lab-teaching"><strong>先预测，再验证</strong><p>${h[1]}</p><p><b>试一试：</b>${h[2]}</p><button class="text-link" data-lesson="${h[0]}">回到对应课程 →</button></div>`}
function learningHome(){const next=lessons.find(l=>l.id===learningNext()),g=lessonGuides[next.id];app.innerHTML=heading('今天，从一个问题开始','学懂一个概念，算对一个小例子，再读懂一条规则。','学习工作台')+`<section class="focus-card"><span class="tag">${completed.length?'继续学习':'零基础起点'} · 约 ${next.minutes} 分钟</span><h2>${next.title}</h2><p>${g.goal}</p><div class="focus-actions"><button class="primary dark" data-lesson="${next.id}">开始这节课 <span>→</span></button><a class="secondary" href="#courses">查看学习路线</a></div><div class="focus-footer"><span>目标 → 示例 → 独立练习</span><span>本机进度 ${completed.length} / ${lessons.length}</span></div><div class="progress-track"><div class="progress-fill" style="width:${completed.length/lessons.length*100}%"></div></div></section><div class="workspace-grid"><section><div class="section-head"><h2>循序渐进的学习路线</h2><span class="subtitle">${lessons.length} 节课</span></div><div class="route-list">${learningGroups.map((s,i)=>`<a href="#courses" class="route-row"><span class="route-index">0${i+1}</span><div><h3>${s.title}</h3><p>${s.desc}</p></div><span class="route-state">${s.ids.filter(id=>completed.includes(id)).length}/${s.ids.length} →</span></a>`).join('')}</div></section><section><div class="section-head"><h2>学习工具</h2></div><div class="tool-list"><a href="#lab/energy"><strong>算例实验室 ↗</strong><p>先预测，再改变参数，解释结果为什么变。</p></a><a href="#rules"><strong>规则资料库 ↗</strong><p>站内阅读原件，核对主体、版本和条款。</p></a><a href="#planner"><strong>光储盈利规划 ↗</strong><p>先学光储收益入门课，再填项目数据。</p></a><a href="#international"><strong>国际市场比较 ↗</strong><p>用同一组问题比较各国与区域市场。</p></a><a href="#resources"><strong>教材与公开课程 ↗</strong><p>按开放程度选择原始资料，沿导读继续学习。</p></a></div>${completed.length?`<button class="secondary review-action" data-lesson="${completed[0]}">复习一节已学课程 ↻</button>`:''}</section></div><section class="starter-note"><strong>第一次来？只需要会加减乘除。</strong><p>先从单位和电费开始。不懂的术语可以随时展开解释；省级原件和复杂盈利参数放在基础课程之后阅读。</p></section>`}
function learningCourses(){academyCourses()}
function learningLesson(id){const l=lessons.find(x=>x.id===id),g=lessonGuides[id];if(!l||!g)return;const dialog=document.getElementById('lessonDialog'),followingId=learningOrder[learningOrder.indexOf(id)+1];let step=0,passed=completed.includes(id);const paint=()=>{
 disposeLessonAnimations();
 document.getElementById('lessonContent').innerHTML=`<div class="dialog-top"><span class="tag">课程 ${learningOrder.indexOf(id)+1} / ${lessons.length} · ${l.minutes} 分钟</span><button class="close" aria-label="关闭课程">×</button></div><h2>${l.title}</h2><nav class="lesson-steps" aria-label="教学步骤">${['学习目标','讲解与示例','自己练一练'].map((t,i)=>`<button data-step="${i}" class="${i===step?'active':''}" ${i===step?'aria-current="step"':''}>${i+1}. ${t}</button>`).join('')}</nav><div class="lesson-body">${step===0?`<div class="lesson-goal"><span>学完后，你能做到</span><h3>${g.goal}</h3></div><p>${l.desc}</p><p class="subtitle">${g.pre.length?'建议先学：'+g.pre.map(id=>lessons.find(x=>x.id===id).title).join('、'):'无需电力专业基础，先把单位对应起来。'}</p><h3>这节课会遇到的词</h3>${g.terms.map(t=>`<details class="term-definition"><summary>${t}</summary><p>${glossary[t]}</p></details>`).join('')}`:step===1?`${l.sections.map(([t,p],i)=>`<h3>${t}</h3><p>${p}</p>${i===0?lessonAnimation(id):''}`).join('')}<div class="worked-example"><span class="tag">完整示例</span><h3>${g.example[0]}</h3><p>${g.example[1]}</p></div>${lessonFurtherReading(l)}${l.lab?'<p class="subtitle">先用上面的过程预测结果，再去实验室只改变一个参数。</p>':''}`:`<div class="quiz"><strong>${g.task?'换一组条件，独立算一次':l.quiz.q}</strong>${g.task?`<p>${g.task[0]}</p><label>你的答案（${g.task[2]}）<input id="practiceAnswer" type="number" step="any" inputmode="decimal"></label><button id="checkPractice" class="secondary">检查答案</button><details><summary>需要一点提示？</summary><p>${g.task[3]}</p></details>`:l.quiz.options.map((o,i)=>`<button data-answer="${i}">${o}</button>`).join('')}<div id="quizFeedback" role="status">${passed?'本课已完成，可再次练习。':'先回答，再查看解释。'}</div></div>${lessonResearchTask(l)}<p class="subtitle">${l.lab?'完成后去对应算例，再改变一个参数说明原因。':id===12?'下一步：打开光储规划，替换演示数据，并核对当地资格和完整成本。':'完成后，用自己的话解释这节课的核心概念。'}</p>`}</div>${step===1?'<button class="secondary lesson-download" id="downloadLesson">下载本课讲义 ↓</button>':''}<div class="modal-actions">${step>0?'<button class="secondary" id="prevStep">上一步</button>':''}${step<2?'<button class="primary dark" id="nextStep">'+(step===0?'开始讲解':'去独立练习')+' →</button>':`<button class="primary dark" id="markDone" ${passed?'':'disabled'}>${completed.includes(id)?'已学完 ✓':'完成本课'}</button>${l.lab?'<button class="secondary" id="toLab">动手做对应算例 ↗</button>':id===12?'<button class="secondary" id="toPlanner">打开光储规划 ↗</button>':''}`} ${step===2&&followingId!==undefined?`<button class="secondary" id="nextLesson" ${completed.includes(id)?'':'disabled'}>下一课 →</button>`:''}<span class="step-label">${step+1} / 3</span></div>`;
 if(step===1)mountLessonAnimations(dialog);const reading=dialog.querySelector('[data-lesson-resources]');if(reading)reading.onclick=()=>{disposeLessonAnimations();dialog.close()};const notes=document.getElementById('downloadLesson');if(notes)notes.onclick=()=>downloadLessonNotes(l,g);dialog.querySelector('.close').onclick=()=>{disposeLessonAnimations();dialog.close()};dialog.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.step);paint();dialog.scrollTop=0});
 if(step<2)document.getElementById('nextStep').onclick=()=>{step++;paint();dialog.scrollTop=0};if(step>0)document.getElementById('prevStep').onclick=()=>{step--;paint();dialog.scrollTop=0};
 if(step===2){const feedback=(correct,explain)=>{document.getElementById('quizFeedback').textContent=(correct?'✓ 回答正确。':g.task?'还差一步，检查单位、参考电量和正负号。':'再看一下概念的定义和适用范围。')+explain;if(correct){passed=true;document.getElementById('markDone').disabled=false}};
 if(g.task)document.getElementById('checkPractice').onclick=()=>{const raw=document.getElementById('practiceAnswer').value,n=Number(raw);if(!raw.trim()||!Number.isFinite(n)){document.getElementById('quizFeedback').textContent='先填写一个有效数字。';return}feedback(Math.abs(n-g.task[1])<0.005,g.task[3])};else dialog.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const correct=Number(b.dataset.answer)===l.quiz.answer;b.className=correct?'correct':'wrong';feedback(correct,l.quiz.explain)});
 document.getElementById('markDone').onclick=()=>{if(!passed)return;if(!completed.includes(id))completed.push(id);let saved=true;try{localStorage.setItem('power-learning-completed',JSON.stringify(completed))}catch{saved=false}document.getElementById('markDone').textContent='已学完 ✓';document.getElementById('quizFeedback').textContent=saved?'✓ 本机进度已保存。建议下次先回忆，再复习。':'✓ 本次已完成，浏览器禁止保存；刷新后可能丢失。';render();const nextButton=document.getElementById('nextLesson');if(nextButton)nextButton.disabled=false;};if(followingId!==undefined)document.getElementById('nextLesson').onclick=()=>learningLesson(followingId);if(l.lab)document.getElementById('toLab').onclick=()=>{dialog.close();location.hash='lab/'+l.lab};if(id===12)document.getElementById('toPlanner').onclick=()=>{dialog.close();location.hash='planner'};
 }
 };paint();if(!dialog.open)dialog.showModal();
}
